import java.io.*;
import java.util.*;
import org.minima.system.commands.*;
import org.minima.objects.Address;
import org.minima.objects.base.*;
import org.minima.utils.json.*;
import org.minima.utils.json.parser.JSONParser;
public class CommandOracle {
    static JSONObject runQuiet(Command command)throws Exception{var output=System.out;try{System.setOut(System.err);return command.runCommand();}finally{System.setOut(output);}}

    static class Test extends Command {Test(String name,String help){super(name,help);}public JSONObject runCommand(){return getJSONReply();}public Command getFunction(){return new Test(getName(),getHelp());}}
    public static void main(String[] args)throws Exception{Locale.setDefault(Locale.ENGLISH);var input=new BufferedReader(new InputStreamReader(System.in));org.minima.database.MinimaDB.createDB();var wallet=org.minima.database.MinimaDB.getDB().getWallet();
        for(String field:new String[]{"mAllTrackedAddress","mAllSimpleAddress"}){var f=wallet.getClass().getDeclaredField(field);f.setAccessible(true);var addresses=(HashSet<String>)f.get(wallet);addresses.add("0x"+"11".repeat(32));addresses.add("0x"+(field.equals("mAllTrackedAddress")?"22":"33").repeat(32));}
        String line;while((line=input.readLine())!=null)try{var data=(JSONObject)new JSONParser().parse(line);String op=(String)data.get("op");if(op.equals("sigfixture")){var key=new org.minima.objects.keys.TreeKey(new MiniData("0x000102"),2,2);key.setUses(Integer.parseInt((String)data.get("uses")));var message=new MiniData((String)data.get("data"));var signature=key.sign(message);var fixture=new JSONObject();fixture.put("publickey",key.getPublicKey().to0xString());fixture.put("data",message.to0xString());fixture.put("signature",MiniData.getMiniDataVersion(signature).to0xString());System.out.println(fixture.toJSONString());continue;}
        if(op.equals("integer")){System.out.println(Integer.parseInt((String)data.get("value")));continue;}
        if(op.equals("mx")){System.out.println(JSONValue.toJSONString(Address.makeMinimaAddress(new MiniData((String)data.get("value")))));continue;}if(op.equals("command")||op.equals("commandmeta")){String name=(String)data.get("command");Command cmd=switch(name){case "debugflag"->new org.minima.system.commands.base.debugflag();case "txnlock"->new org.minima.system.commands.txn.txnlock();case "convert"->new org.minima.system.commands.base.convert();case "random"->new org.minima.system.commands.base.random();case "checkaddress"->new org.minima.system.commands.base.checkaddress();case "maths"->new org.minima.system.commands.base.maths();case "mmrcreate"->new org.minima.system.commands.base.mmrcreate();case "mmrproof"->new org.minima.system.commands.base.mmrproof();case "runscript"->new org.minima.system.commands.scripts.runscript();case "verify"->new org.minima.system.commands.signatures.verify();default->throw new IllegalArgumentException(name);};cmd.getParams().putAll((JSONObject)data.get("params"));if(op.equals("commandmeta")){var meta=new JSONObject();meta.put("name",cmd.getName());meta.put("help",cmd.getHelp());meta.put("fullhelp",cmd.getFullHelp());meta.put("valid",cmd.getValidParams());meta.put("fresh",cmd.getFunction().getJSONReply());System.out.println(meta.toJSONString());}else System.out.println(runQuiet(cmd).toJSONString());continue;}
        if(op.equals("hash")||op.equals("hashmeta")||op.equals("missing")){Command cmd=op.equals("missing")?new org.minima.system.commands.base.missingcmd((String)data.get("input"),(String)data.get("error")):new org.minima.system.commands.base.hash();cmd.getParams().putAll((JSONObject)data.get("params"));if(op.equals("hashmeta")){var meta=new JSONObject();meta.put("help",cmd.getFullHelp());meta.put("valid",cmd.getValidParams());meta.put("fresh",cmd.getFunction().getJSONReply());System.out.println(meta.toJSONString());}else System.out.println(runQuiet(cmd).toJSONString());continue;}var command=new Test((String)data.get("name"),(String)data.get("help"));command.getParams().putAll((JSONObject)data.get("params"));command.setCompleteCommand((String)data.get("complete"));command.setMiniDAPPID((String)data.get("id"));String key=(String)data.get("key");Object value;switch(op){
        case "param":value=command.getParam(key);break;case "paramdefault":value=command.getParam(key,(String)data.get("default"));break;case "boolean":value=command.getBooleanParam(key);break;case "booleandefault":value=command.getBooleanParam(key,(boolean)data.get("default"));break;
        case "number":value=command.getNumberParam(key).toString();break;case "numberdefault":{MiniNumber n=command.getNumberParam(key,data.get("default")==null?null:new MiniNumber((String)data.get("default")));value=n==null?null:n.toString();break;}
        case "data":value=command.getDataParam(key).to0xString();break;case "datadefault":{MiniData d=command.getDataParam(key,data.get("default")==null?null:new MiniData((String)data.get("default")));value=d==null?null:d.to0xString();break;}
        case "address":value=command.getAddressParam(key);break;case "addressdefault":value=command.getAddressParam(key,(String)data.get("default"));break;
        case "object":value=command.getJSONObjectParam(key);break;case "objectdefault":value=command.getJSONObjectParam(key,(JSONObject)data.get("default"));break;case "array":value=command.getJSONArrayParam(key);break;
        case "meta":{var meta=new JSONObject();meta.put("name",command.getName());meta.put("help",command.getHelp());meta.put("fullhelp",command.getFullHelp());meta.put("complete",command.getCompleteCommand());meta.put("id",command.getMiniDAPPID());meta.put("exists",command.existsParam(key));meta.put("object",command.isParamJSONObject(key));meta.put("array",command.isParamJSONArray(key));meta.put("valid",command.getValidParams());value=meta;break;}
        case "reply":{var reply=command.getJSONReply();command.getParams().put("later",true);value=reply;break;}
        case "alias":{var nested=command.getJSONObjectParam(key);if(nested!=null)nested.put("later",true);value=command.getJSONReply();break;}
        default:throw new Exception();}
        System.out.println(JSONValue.toJSONString(value));
    }catch(CommandException e){System.out.println(JSONValue.toJSONString("COMMAND_ERROR:"+e.getMessage()));}catch(Exception e){System.out.println("\"ERROR\"");}}
}
